#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct EvolutionCandidate4{pub candidate_id:String,pub parent_ids:Vec<String>,pub change_kind:String,pub evidence_digest:ContentHash,pub baseline_digest:ContentHash,pub replay_identity:ContentHash,pub deterministic:bool,pub bounded:bool,pub local:bool,pub aggregate_only:bool,pub negative_result:bool,pub safety_impact:String}
