impl BoundedEvolutionCard7{pub fn validate(&self)->Result<(),BoundedEvolutionError>{if self.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||!ne(&self.contract_version)||!ne(&self.feature_id)||!ne(&self.mode)||!ne(&self.scale)||!ne(&self.request_id)||self.boundary!=PRECLINICAL_BOUNDARY||!self.raw_data_local||!self.aggregate_only||self.candidate_order.is_empty()||!ord(&self.candidate_order)||!ord(&self.promoted_order)||!ord(&self.rejected_order)||!ord(&self.unknown_order)||!ord(&self.omitted_order)||!ord(&self.benchmark_order)||!ord(&self.review_order)||!ord(&self.uncertainty_order)||!ord(&self.negative_evidence_order)||!ord(&self.migration_order)||!dig(&self.replay_identity)||!dig(&self.evolution_digest)||self.artifact.content_type!=CONTENT_TYPE||self.artifact.content_hash!=self.evolution_digest||self.artifact.boundary!=PRECLINICAL_BOUNDARY{return Err(BoundedEvolutionError::Output("evolution identity, ordering, locality, digest, or artifact is invalid".into()))}let ids=BTreeSet::from_iter(self.candidate_order.iter().cloned());let parts=self.promoted_order.iter().chain(&self.rejected_order).chain(&self.unknown_order).chain(&self.omitted_order).cloned().collect::<Vec<_>>();if ids.len()!=self.candidate_order.len()||parts.len()!=ids.len()||BTreeSet::from_iter(parts)!=ids{return Err(BoundedEvolutionError::Output("candidate states do not partition".into()))}Ok(())}}
pub fn promote(request:&BoundedEvolutionRequest4,id:&str,version:&str,scale:&str,mode:&str)->Result<BoundedEvolutionCard7,BoundedEvolutionError>{if !ne(&request.request_id)||!ne(&request.scope)||request.candidates.is_empty()||request.required_candidate_order.is_empty()||request.benchmark_order.is_empty()||!dig(&request.replay_identity)||request.boundary!=PRECLINICAL_BOUNDARY||!request.raw_data_local||!request.aggregate_only||!ord(&request.required_candidate_order)||!ord(&request.benchmark_order)||!ord(&request.adversarial_events){return Err(BoundedEvolutionError::Invalid("evolution identity, requirements, digest, ordering, locality, or boundary is invalid".into()))}let mut rows=request.candidates.clone();rows.sort_by(|a,b|a.candidate_id.cmp(&b.candidate_id));let mut seen=BTreeSet::new();let mut order=Vec::new();let mut promoted=BTreeSet::new();let mut rejected=BTreeSet::new();let mut unknown:BTreeSet<String>=BTreeSet::new();let mut omitted=BTreeSet::new();let mut uncertainty=BTreeSet::new();let mut negative=BTreeSet::new();let mut migrations=BTreeSet::new();let mut digests=BTreeSet::new();for c in &rows{if !seen.insert(c.candidate_id.clone())||!ne(&c.candidate_id)||!ord(&c.parent_ids)||!ne(&c.change_kind)||!dig(&c.evidence_digest)||!dig(&c.baseline_digest)||!dig(&c.replay_identity)||!ne(&c.safety_impact)||!c.local||!c.aggregate_only{return Err(BoundedEvolutionError::Invalid("candidate identity, digest, safety, or locality is invalid".into()))}order.push(c.candidate_id.clone());digests.insert(c.evidence_digest.clone());if c.negative_result{negative.insert(format!("{}:negative-result",c.candidate_id));}if c.replay_identity!=request.replay_identity{omitted.insert(c.candidate_id.clone());}else if !c.deterministic||!c.bounded||c.safety_impact!="no-new-physical-effect"{rejected.insert(c.candidate_id.clone());uncertainty.insert(format!("{}:safety-or-bound",c.candidate_id));}else if c.evidence_digest!=c.baseline_digest{rejected.insert(c.candidate_id.clone());migrations.insert(format!("{}:baseline-migration",c.candidate_id));}else{promoted.insert(c.candidate_id.clone());}}let global=!request.policy_allowed||!request.protected_closure||!request.signed_approval||!request.independent_review||!request.raw_data_local||!request.aggregate_only||!request.adversarial_events.is_empty()||request.action_count>request.action_budget;if global{omitted.extend(order.iter().cloned());promoted.clear();rejected.clear();unknown.clear();}let missing=!request.required_candidate_order.iter().all(|c|seen.contains(c));let disposition=if global{"blocked"}else if missing{"unknown"}else if !rejected.is_empty()||!unknown.is_empty()||!omitted.is_empty(){"partial"}else{"promoted"};let mut payload=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":version,"feature_id":id,"mode":mode,"scale":scale,"request_id":request.request_id,"disposition":disposition,"candidate_order":order,"promoted_order":promoted.into_iter().collect::<Vec<_>>(),"rejected_order":rejected.into_iter().collect::<Vec<_>>(),"unknown_order":unknown.into_iter().collect::<Vec<_>>(),"omitted_order":omitted.into_iter().collect::<Vec<_>>(),"benchmark_order":request.benchmark_order,"review_order":vec!["independent-review"],"uncertainty_order":uncertainty.into_iter().collect::<Vec<_>>(),"negative_evidence_order":negative.into_iter().collect::<Vec<_>>(),"migration_order":migrations.into_iter().collect::<Vec<_>>(),"replay_identity":request.replay_identity,"raw_data_local":true,"aggregate_only":true,"boundary":PRECLINICAL_BOUNDARY});let digest=ContentHash::of_value(&payload).map_err(|e|BoundedEvolutionError::Output(e.to_string()))?;payload["evolution_digest"]=json!(digest);payload["artifact"]=json!({"artifact_id":format!("worldgen-bounded-evolution:{}",request.request_id),"content_type":CONTENT_TYPE,"content_hash":digest,"semantic_loss":payload["omitted_order"],"candidate_digests":digests.into_iter().collect::<Vec<_>>(),"boundary":PRECLINICAL_BOUNDARY});payload["effect_receipts"]=json!(if disposition=="promoted"{vec![format!("emit:evolution-card:{}",request.request_id)]}else{vec!["block:unsafe-release".to_string()]});let out:BoundedEvolutionCard7=serde_json::from_value(payload).map_err(|e|BoundedEvolutionError::Output(e.to_string()))?;out.validate()?;Ok(out)}
